contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint initialPotSeed) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (10));
        require(address(this).balance >= 10);
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        // ensure the initial pot is zero by not making any prior play calls
        c.play{value: 10}(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        assert(potAfter == 0 || potAfter == potBefore + 10);
    }
    receive() external payable {}
}

